CREATE TABLE website_photos(id TEXT PRIMARY KEY, object_key TEXT NOT NULL UNIQUE, preview_key TEXT, name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, collection TEXT NOT NULL, caption TEXT NOT NULL DEFAULT '', published INTEGER NOT NULL DEFAULT 0, featured INTEGER NOT NULL DEFAULT 0, position INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE website_uploads(id TEXT PRIMARY KEY, object_key TEXT NOT NULL, upload_id TEXT NOT NULL, name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, collection TEXT NOT NULL, parts TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL);
